// ─── Types ────────────────────────────────────────────────────────────────────
type NVDCve = {
  id: string;
  published: string;
  lastModified: string;
  vulnStatus: string;
  descriptions: { lang: string; value: string }[];
  metrics?: {
    cvssMetricV31?: { cvssData: { baseScore: number; baseSeverity: string; vectorString: string }; exploitabilityScore: number; impactScore: number }[];
    cvssMetricV30?: { cvssData: { baseScore: number; baseSeverity: string } }[];
    cvssMetricV2?:  { cvssData: { baseScore: number } }[];
  };
  references?: { url: string; source: string }[];
  weaknesses?: { description: { lang: string; value: string }[] }[];
};

type KEVEntry = {
  cveID: string;
  vendorProject: string;
  product: string;
  vulnerabilityName: string;
  dateAdded: string;
  shortDescription: string;
  requiredAction: string;
  dueDate: string;
  knownRansomwareCampaignUse: string;
};

type DBItem = {
  id: string;
  title: string;
  link: string;
  excerpt: string | null;
  severity: string;
  source_name: string;
  published_at: string;
  iocs: { cves?: string[] } | null;
  ai_summary?: string | null;
  ai_summary_model?: string | null;
  ai_summary_generated_at?: string | null;
};

// ─── Helpers ──────────────────────────────────────────────────────────────────
function nvdSeverity(cve: NVDCve): string {
  const s = cve.metrics?.cvssMetricV31?.[0]?.cvssData.baseScore
         ?? cve.metrics?.cvssMetricV30?.[0]?.cvssData.baseScore
         ?? cve.metrics?.cvssMetricV2?.[0]?.cvssData.baseScore;
  if (s == null) return "medium";
  if (s >= 9.0) return "critical";
  if (s >= 7.0) return "high";
  if (s >= 4.0) return "medium";
  return "low";
}

function nvdScore(cve: NVDCve): number | null {
  return cve.metrics?.cvssMetricV31?.[0]?.cvssData.baseScore
      ?? cve.metrics?.cvssMetricV30?.[0]?.cvssData.baseScore
      ?? null;
}

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function daysAgo(n: number) {
  return new Date(Date.now() - n * 864e5).toISOString().slice(0, 10);
}

const SEV: Record<string, string> = {
  critical: "bg-destructive/15 text-destructive border-destructive/40",
  high:     "bg-orange-500/15 text-orange-400 border-orange-500/40",
  medium:   "bg-yellow-500/15 text-yellow-400 border-yellow-500/40",
  low:      "bg-blue-500/15 text-blue-400 border-blue-500/40",
};

function CopyBtn({ value }: { value: string }) {
  const [ok, setOk] = useState(false);
  return (
    <button
      onClick={(e) => { e.stopPropagation(); navigator.clipboard.writeText(value).then(() => { setOk(true); setTimeout(() => setOk(false), 1500); }); }}
      className="shrink-0 rounded p-0.5 text-muted-foreground hover:text-foreground"
      title="Copy"
    >
      {ok ? <Check className="h-3 w-3 text-green-500" /> : <Copy className="h-3 w-3" />}
    </button>
  );
}

// ─── NVD Card ─────────────────────────────────────────────────────────────────
function NVDCard({ cve, kev }: { cve: NVDCve; kev: Set<string> }) {
  const desc = cve.descriptions.find((d) => d.lang === "en")?.value || "";
  const score = nvdScore(cve);
  const sev = nvdSeverity(cve);
  const isKEV = kev.has(cve.id);
  const cwe = cve.weaknesses?.[0]?.description?.find((d) => d.lang === "en")?.value;

  return (
    <Card className={`border-border/60 bg-card/60 backdrop-blur hover:border-primary/40 transition-all ${isKEV ? "ring-1 ring-destructive/40" : ""}`}>
      <CardHeader className="pb-2">
        <div className="flex flex-wrap gap-1.5 mb-1.5">
          <Badge className={`border text-[10px] ${SEV[sev]}`}>{sev.toUpperCase()}</Badge>
          {score && <Badge variant="outline" className="font-mono text-[10px]">CVSS {score.toFixed(1)}</Badge>}
          {isKEV && (
            <Badge className="border text-[10px] bg-destructive/20 text-destructive border-destructive/40 flex items-center gap-1">
              <Zap className="h-2.5 w-2.5" /> KEV
            </Badge>
          )}
          {cwe && <Badge variant="outline" className="text-[10px] font-mono">{cwe}</Badge>}
        </div>
        <div className="flex items-start gap-1.5">
          <a
            href={`https://nvd.nist.gov/vuln/detail/${cve.id}`}
            target="_blank"
            rel="noopener noreferrer"
            className="font-mono font-semibold text-sm hover:text-primary transition-colors"
          >
            {cve.id}
          </a>
          <CopyBtn value={cve.id} />
          <span className="text-xs text-muted-foreground ml-auto shrink-0">{timeAgo(cve.published)}</span>
        </div>
      </CardHeader>
      <CardContent className="pt-0">
        <p className="text-sm text-muted-foreground line-clamp-3">{desc}</p>
        <div className="mt-2 flex flex-wrap gap-1.5">
          {[
            { label: "NVD", url: `https://nvd.nist.gov/vuln/detail/${cve.id}` },
            { label: "MITRE", url: `https://cve.mitre.org/cgi-bin/cvename.cgi?name=${cve.id}` },
            { label: "Vulners", url: `https://vulners.com/cve/${cve.id}` },
            { label: "PoC", url: `https://github.com/search?q=${cve.id}&type=repositories` },
          ].map((l) => (
            <a
              key={l.label}
              href={l.url}
              target="_blank"
              rel="noopener noreferrer"
              className="text-[10px] px-1.5 py-0.5 rounded border border-border/50 bg-card/40 hover:border-primary/40 hover:text-primary transition-all flex items-center gap-0.5"
            >
              {l.label} <ExternalLink className="h-2 w-2" />
            </a>
          ))}
        </div>
        <div className="mt-2 text-[10px] text-muted-foreground">
          Status: {cve.vulnStatus} · Modified: {new Date(cve.lastModified).toLocaleDateString()}
        </div>
      </CardContent>
    </Card>
  );
}

// ─── KEV Card ─────────────────────────────────────────────────────────────────
function KEVCard({ v }: { v: KEVEntry }) {
  const isRansomware = v.knownRansomwareCampaignUse === "Known";
  return (
    <Card className="border-destructive/30 bg-destructive/5 backdrop-blur hover:border-destructive/60 transition-all">
      <CardHeader className="pb-2">
        <div className="flex flex-wrap gap-1.5 mb-1.5">
          <Badge className="border text-[10px] bg-destructive/20 text-destructive border-destructive/40">CRITICAL · ACTIVELY EXPLOITED</Badge>
          {isRansomware && <Badge className="border text-[10px] bg-orange-500/20 text-orange-400 border-orange-500/40">RANSOMWARE</Badge>}
        </div>
        <div className="flex items-start gap-1.5">
          <a
            href={`https://nvd.nist.gov/vuln/detail/${v.cveID}`}
            target="_blank"
            rel="noopener noreferrer"
            className="font-mono font-semibold text-sm hover:text-primary transition-colors"
          >
            {v.cveID}
          </a>
          <CopyBtn value={v.cveID} />
          <span className="text-xs text-muted-foreground ml-auto shrink-0">Added {new Date(v.dateAdded).toLocaleDateString()}</span>
        </div>
        <CardTitle className="text-sm leading-snug font-normal text-foreground/90">
          {v.vendorProject} {v.product} — {v.vulnerabilityName}
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-0">
        <p className="text-sm text-muted-foreground line-clamp-2">{v.shortDescription}</p>
        <div className="mt-2 rounded px-2 py-1.5 bg-destructive/10 border border-destructive/20">
          <p className="text-[11px] font-medium text-destructive">Required action by {v.dueDate}:</p>
          <p className="text-[11px] text-muted-foreground mt-0.5">{v.requiredAction}</p>
        </div>
      </CardContent>
    </Card>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function Vulnerabilities() {
  const { toast } = useToast();
  const [searchParams, setSearchParams] = useSearchParams();

  const paramTab = searchParams.get("tab") as "kev" | "nvd" | "feed" | null;
  const [tab, setTab] = useState<"kev" | "nvd" | "feed">(paramTab || "kev");

  useEffect(() => {
    if (paramTab && ["kev", "nvd", "feed"].includes(paramTab)) setTab(paramTab as any);
  }, [paramTab]);
  const [kevData, setKevData] = useState<KEVEntry[]>([]);
  const [nvdData, setNvdData] = useState<NVDCve[]>([]);
  const [dbItems, setDbItems] = useState<DBItem[]>([]);
  const [kevSet, setKevSet] = useState<Set<string>>(new Set());

  const [kevLoading, setKevLoading] = useState(false);
  const [nvdLoading, setNvdLoading] = useState(false);
  const [dbLoading, setDbLoading] = useState(false);

  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [nvdDays, setNvdDays] = useState(7);
  const [nvdQuery, setNvdQuery] = useState("");      // ← live NVD search
  const [kevSearch, setKevSearch] = useState("");
  const [kevRansomOnly, setKevRansomOnly] = useState(false);

  // ── Fetch CISA KEV with multi-layer fallbacks + cache-bust ────────────────
  // Cache-busting timestamp forces both browser and CDN to re-fetch on every
  // call — without this, you can see results that are hours/days stale.
  const fetchKEV = useCallback(async () => {
    setKevLoading(true);
    const ts = Date.now();
    const SOURCES = [
      `https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json?_=${ts}`,
      `https://raw.githubusercontent.com/cisagov/known-exploited-vulnerabilities-catalog/main/known_exploited_vulnerabilities.json?_=${ts}`,
    ];

    let data: any = null;
    for (const url of SOURCES) {
      // serverOnly skips public CORS proxies (they often serve stale copies);
      // go straight to Supabase proxy which fetches a fresh upstream every time.
      const json: any = await liveFetch(url, { serverOnly: true, timeoutMs: 18000 });
      if (!json) continue;
      if (json?.vulnerabilities?.length) { data = json; break; }
      if (Array.isArray(json)) { data = { vulnerabilities: json }; break; }
    }

    if (data) {
      const entries: KEVEntry[] = (data.vulnerabilities || []).sort(
        (a: KEVEntry, b: KEVEntry) => b.dateAdded.localeCompare(a.dateAdded),
      );
      setKevData(entries);
      setKevSet(new Set(entries.map((e) => e.cveID)));
      const newest = entries[0]?.dateAdded ?? "—";
      toast({ title: `CISA KEV refreshed — ${entries.length} CVEs (newest: ${newest})` });
    } else {
      toast({
        title: "CISA KEV unavailable",
        description: "All endpoints temporarily unreachable. Retry shortly.",
        variant: "destructive",
      });
      setKevData([]);
    }
    setKevLoading(false);
  }, [toast]);

  // ── Fetch NVD CVE API (direct from NIST — CORS OK) ───────────────────────
  const fetchNVD = useCallback(async () => {
    setNvdLoading(true);
    try {
      let url: string;
      const q = nvdQuery.trim();

      if (/^CVE-\d{4}-\d{4,7}$/i.test(q)) {
        // Direct CVE lookup
        url = `https://services.nvd.nist.gov/rest/json/cves/2.0?cveId=${encodeURIComponent(q.toUpperCase())}`;
      } else if (q.length >= 3) {
        // Keyword search across NVD
        url = `https://services.nvd.nist.gov/rest/json/cves/2.0?keywordSearch=${encodeURIComponent(q)}&resultsPerPage=100`;
      } else {
        // Date-range listing
        const start = daysAgo(nvdDays);
        const end   = new Date().toISOString().slice(0, 10);
        url = `https://services.nvd.nist.gov/rest/json/cves/2.0?pubStartDate=${start}T00:00:00&pubEndDate=${end}T23:59:59&resultsPerPage=200`;
      }

      // Bulletproof: direct → Supabase proxy → public proxies → 60-min cache.
      const { fetchNvd } = await import("@/lib/nvd-client");
      const data: any = await fetchNvd(url);
      if (!data) {
        toast({ title: "NVD temporarily unreachable", description: "Showing cached results if available.", variant: "default" });
        setNvdData([]);
        setNvdLoading(false);
        return;
      }
      const cves: NVDCve[] = (data.vulnerabilities || []).map((v: any) => v.cve);
      cves.sort((a, b) => b.published.localeCompare(a.published));
      setNvdData(cves);
      if (q && cves.length === 0) {
        toast({ title: "NVD search returned 0 results", description: `No CVEs match "${q}"` });
      }
    } catch (err: any) {
      // fetchNvd should never throw — this is for surrounding logic errors only.
      console.error("[Vulnerabilities] unexpected NVD error", err);
    }
    setNvdLoading(false);
  }, [nvdDays, nvdQuery, toast]);

  // ── Fetch from Supabase DB ─────────────────────────────────────────────────
  const fetchDB = useCallback(async () => {
    setDbLoading(true);
    let { data, error } = await supabase
      .from("threat_items")
      .select("id,title,link,excerpt,severity,source_name,published_at,iocs,ai_summary,ai_summary_model,ai_summary_generated_at")
      .order("published_at", { ascending: false })
      .limit(300);
    if (error?.message?.includes("ai_summary")) {
      const fallback = await supabase
        .from("threat_items")
        .select("id,title,link,excerpt,severity,source_name,published_at,iocs")
        .order("published_at", { ascending: false })
        .limit(300);
      data = fallback.data as any;
      error = fallback.error as any;
    }
    if (error) {
      toast({ title: "DB load failed", description: error.message, variant: "destructive" });
    } else {
      const filtered = (data || []).filter((item: any) => {
        const text = `${item.title} ${item.excerpt || ""}`.toLowerCase();
        return (
          text.includes("cve-") ||
          text.includes("vulnerab") ||
          text.includes("exploit") ||
          text.includes("patch") ||
          text.includes("rce") ||
          text.includes("zero-day") ||
          (item.iocs as any)?.cves?.length > 0
        );
      });
      setDbItems(filtered as DBItem[]);
    }
    setDbLoading(false);
  }, [toast]);

  // Load all on mount
  useEffect(() => { fetchKEV(); fetchNVD(); fetchDB(); }, [fetchKEV, fetchNVD, fetchDB]);
  // Re-fetch NVD when days changes
  useEffect(() => { if (tab === "nvd") fetchNVD(); }, [nvdDays, tab, fetchNVD]);

  // ── Filtered data ─────────────────────────────────────────────────────────
  const filteredKEV = useMemo(() => {
    let out = kevData;
    if (kevRansomOnly) out = out.filter((v) => v.knownRansomwareCampaignUse === "Known");
    if (kevSearch.trim()) {
      const q = kevSearch.trim().toUpperCase();
      out = out.filter((v) =>
        v.cveID.includes(q) ||
        v.vendorProject.toUpperCase().includes(q) ||
        v.product.toUpperCase().includes(q) ||
        v.vulnerabilityName.toUpperCase().includes(q)
      );
    }
    return out;
  }, [kevData, kevSearch, kevRansomOnly]);

  const filteredNVD = useMemo(() => {
    let out = nvdData;
    if (sevFilter !== "all") out = out.filter((c) => nvdSeverity(c) === sevFilter);
    if (search.trim()) {
      const q = search.trim().toUpperCase();
      out = out.filter((c) =>
        c.id.includes(q) ||
        (c.descriptions.find((d) => d.lang === "en")?.value || "").toUpperCase().includes(q)
      );
    }
    return out;
  }, [nvdData, sevFilter, search]);

  const filteredDB = useMemo(() => {
    const q = search.trim().toLowerCase();
    let out = dbItems;
    if (sevFilter !== "all") out = out.filter((i) => i.severity === sevFilter);
    if (q) out = out.filter((i) =>
      i.title.toLowerCase().includes(q) ||
      (i.excerpt || "").toLowerCase().includes(q) ||
      (i.iocs?.cves || []).some((c) => c.toLowerCase().includes(q))
    );
    return out;
  }, [dbItems, search, sevFilter]);

  const kevRansomCount = kevData.filter((v) => v.knownRansomwareCampaignUse === "Known").length;
  const nvdCritCount  = nvdData.filter((c) => nvdSeverity(c) === "critical").length;

  const TABS = [
    { id: "kev",  label: `CISA KEV (${kevData.length})`,   desc: "Actively exploited vulnerabilities per CISA — all are critical" },
    { id: "nvd",  label: `NVD Live (${nvdData.length})`,   desc: `CVEs published in last ${nvdDays} days — pulled directly from NIST NVD API` },
    { id: "feed", label: `Feed Articles (${filteredDB.length})`, desc: "Vulnerability-related items ingested from RSS sources" },
  ] as const;

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-2">
          <Shield className="h-6 w-6 text-primary" />
          <h1 className="text-3xl font-bold tracking-tight">Vulnerabilities</h1>
        </div>
        <p className="text-muted-foreground">
          Real-time CVE intelligence from NIST NVD, CISA KEV, and 250+ threat feeds. CISA KEV and NVD data fetches directly — no backend required.
        </p>
      </div>

      {/* KPI row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        {[
          { label: "CISA KEV", value: kevData.length, color: "text-destructive", icon: <AlertTriangle className="h-4 w-4" />, desc: "Actively exploited" },
          { label: "Ransomware-linked", value: kevRansomCount, color: "text-orange-400", icon: <Zap className="h-4 w-4" />, desc: "Known ransomware use" },
          { label: "NVD Critical", value: nvdCritCount, color: "text-primary", icon: <Shield className="h-4 w-4" />, desc: `Last ${nvdDays}d` },
          { label: "Feed Articles", value: dbItems.length, color: "text-blue-400", icon: <TrendingUp className="h-4 w-4" />, desc: "From RSS sources" },
        ].map((k) => (
          <Card key={k.label} className="border-border/60 bg-card/60">
            <CardContent className="p-4">
              <div className={`text-2xl font-bold tabular-nums ${k.color}`}>{k.value}</div>
              <div className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
                {k.icon} {k.label}
              </div>
              <div className="text-[10px] text-muted-foreground mt-0.5">{k.desc}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Tab bar */}
      <div className="flex gap-1 mb-4 rounded-lg border border-border/60 bg-card/40 p-1 w-fit">
        {TABS.map((t) => (
          <button
            key={t.id}
            onClick={() => { setTab(t.id); setSearchParams(t.id === "kev" ? {} : { tab: t.id }); }}
            className={`rounded-md px-4 py-1.5 text-sm font-medium transition-all ${
              tab === t.id ? "bg-primary text-primary-foreground shadow" : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>
      <p className="text-xs text-muted-foreground mb-4">{TABS.find((t) => t.id === tab)?.desc}</p>

      {/* ── CISA KEV Tab ──────────────────────────────────────────────────── */}
      {tab === "kev" && (
        <>
          <div className="flex flex-wrap gap-3 mb-4">
            <LiveSearchInput
              value={kevSearch}
              onChange={setKevSearch}
              placeholder="Search CVE, vendor, product…"
              className="flex-1 min-w-48"
            />
            <Button
              size="sm"
              variant={kevRansomOnly ? "default" : "outline"}
              onClick={() => setKevRansomOnly((v) => !v)}
              className="gap-1.5"
            >
              <Zap className="h-3.5 w-3.5" /> Ransomware Only
            </Button>
            <Button size="sm" variant="outline" onClick={fetchKEV} disabled={kevLoading} className="gap-1.5">
              <RefreshCw className={`h-3.5 w-3.5 ${kevLoading ? "animate-spin" : ""}`} /> Refresh
            </Button>
          </div>
          {kevLoading ? (
            <div className="text-center py-16 text-muted-foreground">Fetching CISA KEV catalog…</div>
          ) : (
            <div className="grid gap-3 md:grid-cols-2">
              {filteredKEV.map((v) => <KEVCard key={v.cveID} v={v} />)}
              {filteredKEV.length === 0 && (
                <div className="col-span-2 text-center py-16 text-muted-foreground">No results match your filter.</div>
              )}
            </div>
          )}
        </>
      )}

      {/* ── NVD Live Tab ──────────────────────────────────────────────────── */}
      {tab === "nvd" && (
        <>
          {/* Live NVD database search — type CVE ID or keyword to query NVD directly */}
          <div className="mb-3 flex gap-2">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
              <Input
                value={nvdQuery}
                onChange={(e) => setNvdQuery(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && fetchNVD()}
                placeholder="Search NVD live: CVE-2024-12345 or 'apache log4j' (Enter to search)"
                className="pl-10 h-10 text-sm font-mono"
              />
            </div>
            <Button onClick={fetchNVD} disabled={nvdLoading} className="gap-2 h-10 px-5">
              <Search className="h-4 w-4" />
              Search NVD
            </Button>
            {nvdQuery && (
              <Button variant="outline" onClick={() => { setNvdQuery(""); fetchNVD(); }} className="h-10">
                Clear
              </Button>
            )}
          </div>
          <div className="flex flex-wrap gap-3 mb-4">
            <LiveSearchInput
              value={search}
              onChange={setSearch}
              placeholder="Filter loaded results…"
              className="flex-1 min-w-48"
            />
            <div className="flex gap-1">
              {["all", "critical", "high", "medium", "low"].map((s) => (
                <Button key={s} size="sm" variant={sevFilter === s ? "default" : "outline"} onClick={() => setSevFilter(s)} className="text-xs capitalize">
                  {s}
                </Button>
              ))}
            </div>
            {!nvdQuery && (
              <div className="flex gap-1">
                {[7, 14, 30, 90].map((d) => (
                  <Button key={d} size="sm" variant={nvdDays === d ? "default" : "outline"} onClick={() => setNvdDays(d)} className="text-xs">
                    {d}d
                  </Button>
                ))}
              </div>
            )}
            <Button size="sm" variant="outline" onClick={fetchNVD} disabled={nvdLoading} className="gap-1.5">
              <RefreshCw className={`h-3.5 w-3.5 ${nvdLoading ? "animate-spin" : ""}`} /> Refresh
            </Button>
          </div>
          {nvdLoading ? (
            <div className="text-center py-16 text-muted-foreground">Fetching CVEs from NIST NVD…</div>
          ) : filteredNVD.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">No CVEs found for this filter.</div>
          ) : (
            <div className="grid gap-3 md:grid-cols-2">
              {filteredNVD.slice(0, 100).map((c) => <NVDCard key={c.id} cve={c} kev={kevSet} />)}
            </div>
          )}
        </>
      )}

      {/* ── Feed Articles Tab ─────────────────────────────────────────────── */}
      {tab === "feed" && (
        <>
          <div className="flex flex-wrap gap-3 mb-4">
            <LiveSearchInput
              value={search}
              onChange={setSearch}
              placeholder="Search CVE-XXXX-XXXXX…"
              className="flex-1 min-w-48"
            />
            <div className="flex gap-1">
              {["all", "critical", "high", "medium", "low"].map((s) => (
                <Button key={s} size="sm" variant={sevFilter === s ? "default" : "outline"} onClick={() => setSevFilter(s)} className="text-xs capitalize">
                  {s}
                </Button>
              ))}
            </div>
          </div>
          {dbLoading ? (
            <div className="text-center py-16 text-muted-foreground">Loading feed data…</div>
          ) : filteredDB.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">
              <Shield className="h-8 w-8 mx-auto mb-3 opacity-30" />
              <p>No feed items found. Deploy edge functions and trigger a sync to populate data.</p>
              <a href="/settings" className="text-primary text-sm hover:underline mt-2 inline-block">Go to Settings → Deploy Guide</a>
            </div>
          ) : (
            <div className="grid gap-4 md:grid-cols-2">
              {filteredDB.map((item) => (
                <Card key={item.id} className="border-border/60 bg-card/60 backdrop-blur hover:border-primary/40 transition-all">
                  <CardHeader className="pb-3">
                    <div className="flex flex-wrap gap-2 mb-2">
                      <Badge className={`border text-[10px] ${SEV[item.severity] || ""}`}>{item.severity.toUpperCase()}</Badge>
                      <Badge variant="outline" className="text-[10px]">{item.source_name}</Badge>
                    </div>
                    <CardTitle className="text-base leading-snug">
                      <a href={item.link} target="_blank" rel="noopener noreferrer" className="hover:text-primary hover:underline">
                        {item.title}
                      </a>
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="pt-0">
                    {item.excerpt && <p className="line-clamp-2 text-sm text-muted-foreground">{item.excerpt}</p>}
                    {item.iocs?.cves && item.iocs.cves.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-1">
                        {item.iocs.cves.slice(0, 5).map((cve) => (
                          <div key={cve} className="flex items-center gap-0.5">
                            <Badge variant="outline" className="font-mono text-[10px]">{cve}</Badge>
                            <CopyBtn value={cve} />
                          </div>
                        ))}
                      </div>
                    )}
                    <div className="mt-3 flex items-center gap-3 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{timeAgo(item.published_at)}</span>
                      <AISummaryDialog
                        summary={item.ai_summary}
                        generatedAt={item.ai_summary_generated_at}
                        model={item.ai_summary_model}
                        title="AI Brief"
                        triggerLabel="AI"
                        className="h-7 px-2 text-[11px]"
                        itemId={item.id}
                        onGenerated={(s, m, g) => setItems(prev => prev.map(i => i.id === item.id ? { ...i, ai_summary: s, ai_summary_model: m, ai_summary_generated_at: g } : i))}
                      />
                      <a href={item.link} target="_blank" rel="noopener noreferrer" className="ml-auto flex items-center gap-1 text-primary hover:underline">
                        Open <ExternalLink className="h-3 w-3" />
                      </a>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}
